const { useState } = React;

function App() {
  const initialState = {
    profileVisibility: '',
    showOnlineStatus: false,
    allowTagging: false,
  };

  const [profileVisibility, setProfileVisibility] = useState(initialState.profileVisibility);
  const [showOnlineStatus, setShowOnlineStatus] = useState(initialState.showOnlineStatus);
  const [allowTagging, setAllowTagging] = useState(initialState.allowTagging);
  const [savedMessage, setSavedMessage] = useState('');

  function handleReset() {
    setProfileVisibility(initialState.profileVisibility);
    setShowOnlineStatus(initialState.showOnlineStatus);
    setAllowTagging(initialState.allowTagging);
    setSavedMessage('');
  }

  function handleSave() {
    // Simple validation: profileVisibility must be selected
    if (!profileVisibility) {
      setSavedMessage('Please select a profile visibility option.');
      return;
    }
    setSavedMessage('Privacy settings saved.');
  }

  return (
    <>
      <style>{`
        * {
          box-sizing: border-box;
        }
        body {
          margin: 0;
          font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
          background: #f9f7f1;
          color: #222;
        }
        header {
          display: flex;
          align-items: center;
          padding: 12px 16px;
          border-bottom: 1px solid #ccc;
          background: white;
          font-weight: 600;
          font-size: 1.25rem;
          user-select: none;
        }
        header button {
          background: none;
          border: none;
          font-size: 1.25rem;
          cursor: pointer;
          margin-right: 12px;
          color: #444;
          padding: 4px 8px;
          border-radius: 4px;
          transition: background-color 0.2s ease;
        }
        header button:hover {
          background-color: #eee;
        }
        main {
          max-width: 360px;
          margin: 24px auto;
          padding: 0 16px 32px;
          background: white;
          border-radius: 8px;
          box-shadow: 0 2px 8px rgb(0 0 0 / 0.1);
        }
        h2 {
          font-weight: 600;
          font-size: 1rem;
          margin-bottom: 12px;
          color: #555;
        }
        fieldset {
          border: none;
          margin: 0 0 24px 0;
          padding: 0;
        }
        label {
          display: flex;
          align-items: center;
          font-size: 1rem;
          margin-bottom: 12px;
          cursor: pointer;
          user-select: none;
          color: #333;
        }
        input[type="radio"], input[type="checkbox"] {
          margin-right: 12px;
          width: 18px;
          height: 18px;
          cursor: pointer;
        }
        hr {
          border: none;
          border-top: 1px solid #ccc;
          margin: 0 0 24px 0;
        }
        .buttons {
          display: flex;
          justify-content: space-between;
          gap: 12px;
        }
        button {
          flex: 1;
          padding: 10px 0;
          font-size: 1rem;
          border-radius: 6px;
          border: 1.5px solid #666;
          background: white;
          cursor: pointer;
          transition: background-color 0.2s ease, border-color 0.2s ease;
          user-select: none;
        }
        button:focus-visible {
          outline: 2px solid #005fcc;
          outline-offset: 2px;
        }
        button:hover {
          background-color: #f0f0f0;
          border-color: #444;
        }
        button.save {
          border-color: #005fcc;
          background-color: #007bff;
          color: white;
        }
        button.save:hover {
          background-color: #005fcc;
          border-color: #004bb5;
        }
        .message {
          margin-top: 16px;
          font-weight: 600;
          color: #007700;
          user-select: none;
        }
        .error {
          color: #cc0000;
        }
      `}</style>
      <header>
        <button aria-label="Go back" onClick={() => alert('Back clicked')}>&lt;</button>
        Privacy
      </header>
      <main>
        <form onSubmit={e => { e.preventDefault(); handleSave(); }}>
          <fieldset>
            <legend><h2>Profile visibility</h2></legend>
            <label>
              <input
                type="radio"
                name="profileVisibility"
                value="Public"
                checked={profileVisibility === 'Public'}
                onChange={e => setProfileVisibility(e.target.value)}
                required
              />
              Public
            </label>
            <label>
              <input
                type="radio"
                name="profileVisibility"
                value="Friends only"
                checked={profileVisibility === 'Friends only'}
                onChange={e => setProfileVisibility(e.target.value)}
              />
              Friends only
            </label>
            <label>
              <input
                type="radio"
                name="profileVisibility"
                value="Private"
                checked={profileVisibility === 'Private'}
                onChange={e => setProfileVisibility(e.target.value)}
              />
              Private
            </label>
          </fieldset>
          <hr />
          <fieldset>
            <label>
              <input
                type="checkbox"
                checked={showOnlineStatus}
                onChange={e => setShowOnlineStatus(e.target.checked)}
              />
              Show online status
            </label>
            <label>
              <input
                type="checkbox"
                checked={allowTagging}
                onChange={e => setAllowTagging(e.target.checked)}
              />
              Allow tagging
            </label>
          </fieldset>
          <div className="buttons">
            <button type="button" onClick={handleReset}>Reset</button>
            <button type="submit" className="save">Save</button>
          </div>
          {savedMessage && (
            <p
              role="alert"
              className={savedMessage === 'Privacy settings saved.' ? 'message' : 'message error'}
              tabIndex={-1}
            >
              {savedMessage}
            </p>
          )}
        </form>
      </main>
    </>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);

